};

const NAV_ITEMS: { key: SectionKey; label: string }[] = [
 { key: "dashboard", label: "Dashboard" },
 { key: "customer-orders", label: "Customer Orders" },
 { key: "production", label: "Production & Machines" },
 { key: "schedule", label: "Schedule Planner" },
 { key: "inventory", label: "Inventory" },
 { key: "procurement", label: "Procurement" },
 { key: "suppliers", label: "Suppliers" },
 { key: "alerts", label: "Alerts & Exceptions" },
 { key: "forecasting", label: "Demand Forecasting" },
 { key: "digital-twin", label: "Digital Twin" },
];

/* ═══════════════════ SHARED COMPONENTS ═══════════════════ */
function Loading({ msg }: { msg?: string }) {
 return <div className="ids-empty"><div className="ids-spinner" /><span style={{ fontSize: 13, color: "var(--ids-text-tertiary)" }}>{msg || "Loading…"}</span></div>;
}

function Empty({ icon, title, desc }: { icon?: string; title: string; desc?: string }) {
 return <div className="ids-empty"><div className="ids-empty-icon" dangerouslySetInnerHTML={{ __html: icon || "—" }} /><div className="ids-empty-title">{title}</div>{desc && <div className="ids-empty-desc">{desc}</div>}</div>;
}

function PageHeader({ title, sub, children }: { title: string; sub?: string; children?: React.ReactNode }) {
 return (
 <div style={{ marginBottom: 24, display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
 <div>
 <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{title}</h1>
 {sub && <p style={{ margin: "6px 0 0", fontSize: 14, color: "var(--ids-text-secondary)" }}>{sub}</p>}
 </div>
 {children}
 </div>
 );
}

function Kpi({ value, label, color, border }: { value: number | string; label: string; color?: string; border?: string; key?: any }) {
 return (
 <div className="ids-kpi" style={{ borderTop: border ? `3px solid ${border}` : undefined }}>
 <span className="ids-kpi-value" style={{ color: color || "var(--ids-brand-navy)" }}>{value}</span>
 <span className="ids-kpi-label">{label}</span>
 </div>
 );
}

function StatRow({ label, value, color }: { label: string; value: number | string; color?: string }) {
 return (
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 0", borderBottom: "1px solid var(--ids-border-light)" }}>
 <span style={{ fontSize: 13, color: "var(--ids-text-secondary)" }}>{label}</span>
 <span style={{ fontSize: 14, fontWeight: 700, color: color || "var(--ids-text-primary)" }}>{value}</span>
 </div>
 );
}

function NavButton({ to, label }: { to: string; label: string }) {
 return (
 <a href={to} target="_self" className="ids-btn ids-btn-accent" style={{ marginTop: 16, textDecoration: "none" }}>
 {label} →
 </a>
 );
}

/* ═══════════════════ SIDEBAR ═══════════════════ */
function Sidebar({ active, onNav, alertCount }: { active: SectionKey; onNav: (k: SectionKey) => void; alertCount: number }) {
 const [hovered, setHovered] = useState<SectionKey | null>(null);
 return (
 <aside style={{ width: 230, minWidth: 230, height: "100vh", background: "#fff", borderRight: "1px solid var(--ids-border)", display: "flex", flexDirection: "column", flexShrink: 0, overflowY: "auto" }}>
 <div style={{ padding: "20px 18px 16px", borderBottom: "1px solid var(--ids-border)" }}>
 <div style={{ fontSize: 15, fontWeight: 700, color: "var(--ids-brand-navy)", lineHeight: 1.3 }}>Industrial Supply Co.</div>
 <div style={{ fontSize: 10.5, fontWeight: 600, color: "var(--ids-text-tertiary)", textTransform: "uppercase", letterSpacing: ".08em", marginTop: 4 }}>Operations Admin</div>
 </div>
 <nav style={{ flex: 1, padding: "6px 0" }}>
 {NAV_ITEMS.map((item) => {
 const isActive = item.key === active;
 const isHover = item.key === hovered && !isActive;
 return (
 <button key={item.key} onClick={() => onNav(item.key)} onMouseEnter={() => setHovered(item.key)} onMouseLeave={() => setHovered(null)}
 style={{ display: "flex", alignItems: "center", gap: 12, width: "100%", padding: "10px 16px", border: "none", background: isActive ? "var(--ids-brand-navy)" : isHover ? "var(--ids-bg-hover)" : "transparent", color: isActive ? "#fff" : "var(--ids-text-primary)", fontSize: 13.5, fontWeight: isActive ? 600 : 400, fontFamily: "inherit", cursor: "pointer", textAlign: "left", borderLeft: isActive ? "3px solid var(--ids-brand-accent)" : "3px solid transparent", transition: "background .12s" }}>
 <span style={{ width: 20, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: isActive ? 1 : .65 }} dangerouslySetInnerHTML={{ __html: ICONS[item.key] || "" }} />
 <span style={{ flex: 1 }}>{item.label}</span>
 {item.key === "alerts" && alertCount > 0 && (
 <span style={{ minWidth: 20, height: 18, padding: "0 6px", borderRadius: 9, background: isActive ? "var(--ids-sev-critical)" : "var(--ids-error)", color: "#fff", fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>{alertCount}</span>
 )}
 </button>
 );
 })}
 </nav>
 <div style={{ padding: "14px 18px", borderTop: "1px solid var(--ids-border)", fontSize: 10, color: "var(--ids-text-tertiary)", textAlign: "center" }}>Industrial Ops v2.0</div>
 </aside>
 );
}

/* ═══════════════════ DASHBOARD LANDING ═══════════════════ */
function DashboardLanding({ onNav }: { onNav: (k: SectionKey) => void }) {
 const [kpis, setKpis] = useState<KpiData | null>(null);
 const [op, setOp] = useState<OperatorData | null>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 let m = true;
 Promise.all([apiFetch<KpiData>(API.kpis), apiFetch<OperatorData>(API.operator)]).then(([k, o]) => { if (m) { setKpis(k); setOp(o); setLoading(false); } });
 return () => { m = false; };
 }, []);

 if (loading) return <Loading msg="Loading dashboard…" />;

 const ao = op?.activeOrders ?? 0, ts = kpis?.totalStock ?? 0, oa = kpis?.alerts?.open ?? op?.activeAlerts ?? 0, ar = op?.availableResources ?? 0;
 const ip = op?.inProgressOrders ?? 0, pl = op?.plannedOrders ?? 0, mt = op?.maintenanceRequired ?? 0;
 const pr = op?.pendingRequests ?? 0, cats = kpis?.categories ?? [], req = kpis?.requests;
 const ac = kpis?.alerts?.critical ?? 0, ah = kpis?.alerts?.high ?? 0;
 const qual = kpis?.quality;
 const txns = kpis?.recentTransactions ?? [];

 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title="Industrial Operations Dashboard" sub="Real-time overview of production, inventory, alerts, and operations" />

 {/* KPI Strip */}
 <div className="ids-grid-4" style={{ marginBottom: 20 }}>
 <Kpi value={ao} label="Active Production Orders" color="var(--ids-brand-navy)" border="var(--ids-brand-navy)" />
 <Kpi value={ts} label="Inventory Stock Items" color="var(--ids-info)" border="var(--ids-info)" />
 <Kpi value={oa} label="Open Alerts" color={oa > 0 ? "var(--ids-error)" : "var(--ids-success)"} border={oa > 0 ? "var(--ids-error)" : "var(--ids-success)"} />
 <Kpi value={ar} label="Available Resources" color="var(--ids-success)" border="var(--ids-success)" />
 </div>

 {/* Production + Customer Orders */}
 <div className="ids-grid-2" style={{ marginBottom: 20 }}>
 <div className="ids-card">
 <h3 className="ids-card-title">Production Overview</h3>
 <StatRow label="In-Progress Orders" value={ip} color="var(--ids-info)" />
 <StatRow label="Planned Orders" value={pl} />
 <StatRow label="Maintenance Required" value={mt} color={mt > 0 ? "var(--ids-error)" : undefined} />
 <button className="ids-btn-link" style={{ marginTop: 14 }} onClick={() => onNav("production")}>View Production Details →</button>
 </div>
 <div className="ids-card">
 <h3 className="ids-card-title">Customer Orders</h3>
 <StatRow label="Pending Requests" value={pr} color={pr > 0 ? "var(--ids-warning)" : undefined} />
 <StatRow label="Pending Approval" value={req?.pendingApproval ?? 0} />
 <StatRow label="In Progress" value={req?.inProgress ?? 0} color="var(--ids-info)" />
 <StatRow label="Completed" value={req?.completed ?? 0} color="var(--ids-success)" />
 <button className="ids-btn-link" style={{ marginTop: 14 }} onClick={() => onNav("customer-orders")}>View All Orders →</button>
 </div>
 </div>

 {/* Inventory Overview */}
 <div className="ids-card" style={{ marginBottom: 20 }}>
 <h3 className="ids-card-title">Inventory Overview</h3>
 {cats.length > 0 ? (
 <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(190px, 1fr))", gap: 12 }}>
 {cats.map((c) => (
 <div key={c.type} style={{ padding: "14px 16px", borderRadius: 8, border: "1px solid var(--ids-border)", background: "var(--ids-bg-surface)" }}>
 <div style={{ fontSize: 12, color: "var(--ids-text-secondary)", marginBottom: 6 }}>{c.label}</div>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
 <span style={{ fontSize: 20, fontWeight: 700, color: "var(--ids-brand-navy)" }}>{c.count}</span>
 <span style={{ fontSize: 11, color: "var(--ids-text-tertiary)" }}>{c.availableQty?.toLocaleString()} units</span>
 </div>
 </div>
 ))}
 </div>
 ) : <div style={{ fontSize: 13, color: "var(--ids-text-tertiary)", padding: "12px 0" }}>No category data available</div>}
 <button className="ids-btn-link" style={{ marginTop: 14 }} onClick={() => onNav("inventory")}>View Full Inventory →</button>
 </div>

 {/* Alerts + Quality */}
 <div className="ids-grid-2" style={{ marginBottom: 20 }}>
 <div className="ids-card">
 <h3 className="ids-card-title">Alert Summary</h3>
 <div className="ids-grid-3" style={{ marginBottom: 12 }}>
 {[{ k: "critical", l: "Critical", v: ac, c: "var(--ids-sev-critical)" }, { k: "high", l: "High", v: ah, c: "var(--ids-sev-high)" }, { k: "open", l: "Open", v: oa, c: "var(--ids-brand-navy)" }].map((x) => (
 <div key={x.k} style={{ textAlign: "center", padding: "10px 0", borderRadius: 8, background: x.v > 0 && x.k !== "open" ? "var(--ids-error-bg)" : "var(--ids-bg-surface)" }}>
 <div style={{ fontSize: 22, fontWeight: 700, color: x.v > 0 ? x.c : "var(--ids-text-tertiary)" }}>{x.v}</div>
 <div style={{ fontSize: 10, fontWeight: 600, color: "var(--ids-text-tertiary)", textTransform: "uppercase" }}>{x.l}</div>
 </div>
 ))}
 </div>
 {ac > 0 && <div className="ids-alert ids-alert-error" style={{ marginBottom: 12 }}>⚠ {ac} critical alert{ac !== 1 ? "s" : ""} require attention</div>}
 <button className="ids-btn-link" onClick={() => onNav("alerts")}>View All Alerts →</button>
 </div>
 <div className="ids-card">
 <h3 className="ids-card-title">Quality Overview</h3>
 <StatRow label="Pending Inspections" value={qual?.pending ?? 0} color="var(--ids-warning)" />
 <StatRow label="Passed" value={qual?.passed ?? 0} color="var(--ids-success)" />
 <StatRow label="Failed" value={qual?.failed ?? 0} color={(qual?.failed ?? 0) > 0 ? "var(--ids-error)" : undefined} />
 <StatRow label="Blocked Batches" value={qual?.blockedBatches ?? 0} color={(qual?.blockedBatches ?? 0) > 0 ? "var(--ids-error)" : undefined} />
 </div>
 </div>

 {/* Recent Transactions */}
 {txns.length > 0 && (
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>Recent Activity</h3>
 </div>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Number</th><th>Material</th><th>Qty</th><th>Type</th><th>Date</th><th>Status</th></tr></thead>
 <tbody>{txns.slice(0, 10).map((t, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600, color: "var(--ids-info)" }}>{t.number}</td>
 <td>{t.material}</td><td style={{ fontFamily: "var(--ids-font-mono)" }}>{t.quantity}</td>
 <td>{t.transactionType?.replace(/_/g, " ")}</td><td style={{ color: "var(--ids-text-tertiary)", whiteSpace: "nowrap" }}>{fmtDate(t.transactionDate)}</td>
 <td><span className="ids-badge ids-badge-info" style={{ textTransform: "capitalize" }}>{t.status}</span></td>
 </tr>
 ))}</tbody>
 </table>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ ALERTS SECTION ═══════════════════ */
function AlertsSection() {
 const [data, setData] = useState<AlertsData | null>(null);
 const [loading, setLoading] = useState(true);
 useEffect(() => { let m = true; apiFetch<AlertsData>(API.alerts).then(d => { if (m) { setData(d); setLoading(false); } }); return () => { m = false; }; }, []);
 if (loading) return <Loading msg="Loading alerts…" />;
 const sum = data?.summary ?? { critical: 0, high: 0, medium: 0, low: 0, open: 0 };
 const alerts = data?.alerts ?? [];
 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title="Alerts & Exceptions" sub="Monitor and manage operational alerts" />
 <div className="ids-grid-4" style={{ marginBottom: 20 }}>
 {([["critical", "Critical", "var(--ids-sev-critical)"], ["high", "High", "var(--ids-sev-high)"], ["medium", "Medium", "var(--ids-sev-medium)"], ["low", "Low", "var(--ids-sev-low)"]] as const).map(([k, l, c]) => (
 <Kpi key={k} value={(sum as any)[k]} label={l} color={c} border={c} />
 ))}
 </div>
 {sum.critical > 0 && <div className="ids-alert ids-alert-error" style={{ marginBottom: 20, fontWeight: 600 }}>⚠ {sum.critical} critical alert{sum.critical !== 1 ? "s" : ""} — immediate action recommended</div>}
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>All Alerts</h3>
 <span style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>{alerts.length} alert{alerts.length !== 1 ? "s" : ""} • {sum.open} open</span>
 </div>
 {alerts.length === 0 ? <Empty title="No alerts found" desc="All systems operating normally." /> : (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Number</th><th>Type</th><th>Severity</th><th style={{ minWidth: 200 }}>Message</th><th>Status</th><th>Date</th></tr></thead>
 <tbody>{alerts.map(a => (
 <tr key={a.sys_id}>
 <td style={{ fontWeight: 600, color: "var(--ids-info)" }}>{a.number}</td>
 <td>{a.alert_type?.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase())}</td>
 <td><span className={sevClass(a.severity)}>{a.severity}</span></td>
 <td style={{ color: "var(--ids-text-secondary)", maxWidth: 320 }}>{a.alert_message}</td>
 <td><span className={`ids-badge ${a.status?.toLowerCase() === "open" ? "ids-badge-open" : "ids-badge-closed"}`}>{a.status}</span></td>
 <td style={{ color: "var(--ids-text-tertiary)", whiteSpace: "nowrap" }}>{fmtDate(a.alert_date)}</td>
 </tr>
 ))}</tbody>
 </table>
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ TABLE DATA SECTION (generic) ═══════════════════ */
function TableSection({ title, sub, url, columns, emptyMsg }: { title: string; sub: string; url: string; columns: { key: string; label: string; render?: (r: any) => React.ReactNode }[]; emptyMsg: string }) {
 const [rows, setRows] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 useEffect(() => {
 let m = true;
 apiFetch<any[]>(url).then(d => { if (m) { setRows(Array.isArray(d) ? d : []); setLoading(false); } });
 return () => { m = false; };
 }, [url]);
 if (loading) return <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}><PageHeader title={title} sub={sub} /><Loading /></div>;
 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title={title} sub={sub} />
 {rows.length === 0 ? <div className="ids-card"><Empty title={emptyMsg} desc="No records found in the system." /></div> : (
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "14px 24px", borderBottom: "1px solid var(--ids-border)", fontSize: 12, color: "var(--ids-text-tertiary)" }}>{rows.length} record{rows.length !== 1 ? "s" : ""}</div>
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr>{columns.map(c => <th key={c.key}>{c.label}</th>)}</tr></thead>
 <tbody>{rows.map((r, i) => (
 <tr key={r.sys_id?.value || r.sys_id || i}>{columns.map(c => <td key={c.key}>{c.render ? c.render(r) : dv(r[c.key])}</td>)}</tr>
 ))}</tbody>
 </table>
 </div>
 </div>
 )}
 </div>
 );
}

/* ═══════════════════ PRODUCTION SECTION ═══════════════════ */
function ProductionSection() {
 const [orders, setOrders] = useState<any[]>([]);
 const [resources, setResources] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 useEffect(() => {
 let m = true;
 Promise.all([apiFetch<any[]>(API.production), apiFetch<any[]>(API.resources)]).then(([o, r]) => {
 if (m) { setOrders(Array.isArray(o) ? o : []); setResources(Array.isArray(r) ? r : []); setLoading(false); }
 });
 return () => { m = false; };
 }, []);
 if (loading) return <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}><PageHeader title="Production & Machines" sub="Monitor production orders and resources" /><Loading /></div>;

 const avail = resources.filter(r => dv(r.status) === "Available" || dv(r.status) === "available").length;
 const maint = resources.filter(r => dv(r.maintenance_required) === "true" || dv(r.maintenance_required) === "Yes").length;

 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title="Production & Machines" sub="Monitor production orders, resources, and machine status">
 <a href="x_2056099_indust_0_manager_mobile.do" className="ids-btn ids-btn-accent" style={{ textDecoration: "none" }}>Open Manager Mobile →</a>
 </PageHeader>

 <div className="ids-grid-4" style={{ marginBottom: 20 }}>
 <Kpi value={orders.length} label="Active Orders" color="var(--ids-brand-navy)" border="var(--ids-brand-navy)" />
 <Kpi value={orders.filter(o => dv(o.status).toLowerCase().includes("progress")).length} label="In Progress" color="var(--ids-info)" border="var(--ids-info)" />
 <Kpi value={avail} label="Available Resources" color="var(--ids-success)" border="var(--ids-success)" />
 <Kpi value={maint} label="Maintenance Required" color={maint > 0 ? "var(--ids-error)" : "var(--ids-text-tertiary)"} border={maint > 0 ? "var(--ids-error)" : "var(--ids-border)"} />
 </div>

 {/* Production Orders */}
 <div className="ids-card" style={{ padding: 0, overflow: "hidden", marginBottom: 20 }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>Production Orders</h3>
 <span style={{ fontSize: 12, color: "var(--ids-text-tertiary)" }}>{orders.length} active order{orders.length !== 1 ? "s" : ""}</span>
 </div>
 {orders.length === 0 ? <Empty title="No active production orders" desc="Create production orders to see them here." /> : (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Number</th><th>Product</th><th>Planned</th><th>Produced</th><th>Status</th><th>Priority</th><th>Resource</th></tr></thead>
 <tbody>{orders.map((o, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600, color: "var(--ids-info)" }}>{dv(o.number)}</td>
 <td>{dv(o.finished_product)}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(o.quantity_planned)}</td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(o.quantity_produced)}</td>
 <td><span className="ids-badge ids-badge-info">{dv(o.status)}</span></td>
 <td><span style={{ fontSize: 12, fontWeight: 600, color: dv(o.priority).toLowerCase() === "critical" ? "var(--ids-sev-critical)" : dv(o.priority).toLowerCase() === "high" ? "var(--ids-sev-high)" : "var(--ids-text-secondary)" }}>{dv(o.priority)}</span></td>
 <td>{dv(o.assigned_resource)}</td>
 </tr>
 ))}</tbody>
 </table>
 </div>
 )}
 </div>

 {/* Resources */}
 <div className="ids-card" style={{ padding: 0, overflow: "hidden" }}>
 <div style={{ padding: "18px 24px 14px", borderBottom: "1px solid var(--ids-border)" }}>
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>Production Resources</h3>
 </div>
 {resources.length === 0 ? <Empty title="No production resources" /> : (
 <div style={{ overflowX: "auto" }}>
 <table className="ids-table">
 <thead><tr><th>Name</th><th>Type</th><th>Status</th><th>Capacity/Day</th><th>Efficiency</th><th>Maintenance</th></tr></thead>
 <tbody>{resources.map((r, i) => (
 <tr key={i}>
 <td style={{ fontWeight: 600 }}>{dv(r.resource_name)}</td>
 <td>{dv(r.resource_type)}</td>
 <td><span className={`ids-badge ${dv(r.status).toLowerCase() === "available" ? "ids-badge-low" : "ids-badge-open"}`}>{dv(r.status)}</span></td>
 <td style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(r.capacity_per_day)}</td>
 <td>{dv(r.efficiency_percentage)}%</td>
 <td>{(dv(r.maintenance_required) === "true" || dv(r.maintenance_required) === "Yes") ? <span style={{ color: "var(--ids-error)", fontWeight: 600 }}>Required</span> : <span style={{ color: "var(--ids-success)" }}>No</span>}</td>
 </tr>
 ))}</tbody>
 </table>
 </div>
 )}
 </div>
 </div>
 );
}

/* ═══════════════════ GATEWAY SECTIONS ═══════════════════ */
function GatewaySection({ title, sub, desc, url, btnLabel, icon }: { title: string; sub: string; desc: string; url: string; btnLabel: string; icon: string }) {
 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title={title} sub={sub} />
 <div className="ids-card" style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "60px 32px", textAlign: "center" }}>
 <div style={{ width: 72, height: 72, borderRadius: 18, background: "var(--ids-bg-surface)", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 20 }} dangerouslySetInnerHTML={{ __html: icon.replace(/width="18"/g, 'width="32"').replace(/height="18"/g, 'height="32"') }} />
 <div style={{ fontSize: 18, fontWeight: 700, color: "var(--ids-text-primary)", marginBottom: 8 }}>{title}</div>
 <div style={{ fontSize: 14, color: "var(--ids-text-secondary)", maxWidth: 500, marginBottom: 24, lineHeight: 1.5 }}>{desc}</div>
 <NavButton to={url} label={btnLabel} />
 </div>
 </div>
 );
}

/* ═══════════════════ PROCUREMENT SECTION ═══════════════════ */
function ProcurementSection({ kpis }: { kpis: KpiData | null }) {
 const req = kpis?.requests;
 return (
 <div style={{ padding: "28px 32px", maxWidth: 1400, margin: "0 auto" }}>
 <PageHeader title="Procurement" sub="Track procurement requests and approvals" />
 <div className="ids-grid-3" style={{ marginBottom: 20 }}>
 {([["Draft", req?.draft ?? 0, "var(--ids-text-secondary)"], ["Pending Approval", req?.pendingApproval ?? 0, "var(--ids-warning)"], ["Approved", req?.approved ?? 0, "var(--ids-success)"], ["In Progress", req?.inProgress ?? 0, "var(--ids-info)"], ["Completed", req?.completed ?? 0, "var(--ids-success)"], ["Rejected", req?.rejected ?? 0, "var(--ids-error)"]] as const).map(([l, v, c], i) => (
 <Kpi key={i} value={v} label={l as string} color={c as string} />
 ))}
 </div>
 </div>
 );
}

/* ═══════════════════ MAIN CONTENT ROUTER ═══════════════════ */
function MainContent({ active, onNav, kpis }: { active: SectionKey; onNav: (k: SectionKey) => void; kpis: KpiData | null }) {
 switch (active) {
 case "dashboard": return <DashboardLanding onNav={onNav} />;
 case "alerts": return <AlertsSection />;
 case "production": return <ProductionSection />;
 case "customer-orders": return <TableSection title="Customer Orders" sub="Track customer orders and delivery" url={API.orders} emptyMsg="No customer orders" columns={[
 { key: "number", label: "Number", render: r => <span style={{ fontWeight: 600, color: "var(--ids-info)" }}>{dv(r.number)}</span> },
 { key: "customer", label: "Customer" }, { key: "product", label: "Product" },
 { key: "order_quantity", label: "Qty", render: r => <span style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(r.order_quantity)}</span> },
 { key: "status", label: "Status", render: r => <span className="ids-badge ids-badge-info">{dv(r.status)}</span> },
 { key: "requested_delivery_date", label: "Delivery Date", render: r => <span style={{ color: "var(--ids-text-tertiary)" }}>{fmtDate(dv(r.requested_delivery_date))}</span> },
 ]} />;
 case "inventory": return <TableSection title="Inventory" sub="Current stock levels and locations" url={API.inventory} emptyMsg="No inventory records" columns={[
 { key: "material_product", label: "Material" }, { key: "location", label: "Location" },
 { key: "available_quantity", label: "Available", render: r => <span style={{ fontFamily: "var(--ids-font-mono)", fontWeight: 600 }}>{dv(r.available_quantity)}</span> },
 { key: "reserved_quantity", label: "Reserved", render: r => <span style={{ fontFamily: "var(--ids-font-mono)" }}>{dv(r.reserved_quantity)}</span> },
 { key: "status", label: "Status", render: r => <span className="ids-badge ids-badge-info">{dv(r.status)}</span> },
 { key: "expiry_date", label: "Expiry", render: r => <span style={{ color: "var(--ids-text-tertiary)" }}>{dv(r.expiry_date) !== "—" ? fmtDate(dv(r.expiry_date)) : "—"}</span> },
 ]} />;
 case "suppliers": return <TableSection title="Suppliers" sub="Manage supplier relationships" url={API.suppliers} emptyMsg="No suppliers configured" columns={[
 { key: "supplier_name", label: "Name", render: r => <span style={{ fontWeight: 600 }}>{dv(r.supplier_name)}</span> },
 { key: "status", label: "Status", render: r => <span className="ids-badge ids-badge-info">{dv(r.status)}</span> },
 { key: "contact_email", label: "Email" }, { key: "city", label: "City" },
 { key: "supplier_rating", label: "Rating", render: r => <span style={{ fontWeight: 600 }}>{dv(r.supplier_rating)}</span> },
 ]} />;
 case "procurement": return <ProcurementSection kpis={kpis} />;
 case "schedule": return <GatewaySection title="Schedule Planner" sub="Create, manage, and confirm production schedules" desc="Plan production schedules using the ProductionScheduler engine. Create draft schedules, review resource allocation, resolve conflicts, and confirm schedules for execution." url="x_2056099_indust_0_production_schedule_planner.do" btnLabel="Open Schedule Planner" icon={ICONS.schedule} />;
 case "digital-twin": return <GatewaySection title="Digital Twin / What-If Planner" sub="Run simulations using real production data" desc="Simulate disruption scenarios using the WhatIfSimulationEngine. Model resource downtime, capacity reductions, material shortages, and schedule shifts with adaptive rescheduling." url="x_2056099_indust_0_whatif_planner.do" btnLabel="Open What-If Planner" icon={ICONS["digital-twin"]} />;
 case "forecasting": return <GatewaySection title="Demand Forecasting" sub="Analyze inventory coverage and demand trends" desc="Review material coverage indicators and demand forecast data. Identify materials at risk of stockout and plan procurement activities." url="x_2056099_indust_0_demand_forecast.do" btnLabel="Open Demand Forecasting" icon={ICONS.forecasting} />;
 default: return <Empty title="Section not found" />;
 }
}

/* ═══════════════════ APP ROOT ═══════════════════ */
function App() {
 const [active, setActive] = useState<SectionKey>("dashboard");
 const [alertCount, setAlertCount] = useState(0);
 const [kpis, setKpis] = useState<KpiData | null>(null);

 const handleNav = useCallback((key: SectionKey) => {
 setActive(key);
 window.location.hash = key;
 }, []);

 useEffect(() => {
 const h = window.location.hash.replace("#", "") as SectionKey;
 if (h && NAV_ITEMS.some(n => n.key === h)) setActive(h);
 }, []);

 // Load alert count + kpis for sidebar badge + procurement
 useEffect(() => {
 apiFetch<KpiData>(API.kpis).then(k => { if (k) { setKpis(k); setAlertCount(k.alerts?.open ?? 0); } });
 }, []);

 return (
 <div style={{ display: "flex", height: "100vh", width: "100%", fontFamily: "var(--ids-font)", margin: 0, padding: 0 }}>
 <Sidebar active={active} onNav={handleNav} alertCount={alertCount} />
 <main style={{ flex: 1, height: "100vh", overflowY: "auto", background: "var(--ids-bg-page)" }}>
 <MainContent active={active} onNav={handleNav} kpis={kpis} />
 </main>
 </div>
 );
}

/* ═══════════════════ MOUNT ═══════════════════ */
const root = document.getElementById("root");
if (root) ReactDOM.createRoot(root).render(<App />);
